-- Keys are fingerprints of the original type, bilingual prompt, options, content and answer.
-- Exact matches only: preserve edits made by individual installations. A null replacement
-- withholds the question from practice and mastery totals until an editor supplies a key.
CREATE FUNCTION pg_temp.arbormed_stored_key(value text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
    IF left(ltrim(value), 1) IN ('[', '{', '"') THEN
        RETURN value::jsonb;
    END IF;
    RETURN to_jsonb(value);
EXCEPTION WHEN invalid_text_representation THEN
    RETURN to_jsonb(value);
END $$;

