UPDATE questions q SET
    active = fixes.replacement IS NOT NULL,
    correct_answer = CASE WHEN fixes.replacement IS NULL THEN q.correct_answer
        ELSE (jsonb_populate_record(NULL::questions, jsonb_build_object('correct_answer', fixes.replacement))).correct_answer END
FROM fixes
WHERE q.active AND fixes.fingerprint = encode(sha256(convert_to(jsonb_build_array(
    COALESCE(NULLIF(q.question_type, ''), q.type, 'single_choice'),
    COALESCE(q.question_text_en, ''), COALESCE(q.question_text_hu, ''),
    q.options::jsonb, COALESCE(q.content::jsonb, '{}'::jsonb),
    pg_temp.arbormed_stored_key(q.correct_answer::text)
)::text, 'UTF8')), 'hex');

DROP FUNCTION pg_temp.arbormed_stored_key(text);
